import panic from "@std/core.ms"

export fn main() Int:
    let values = [1, 2, 3]
    var total = 0
    var count = 0
    for value in values:
        total = total + value
        if count == 0:
            values.without(0)
        count = count + 1
    if total != 4:
        panic("unexpected sum")
    return 0
